<script setup>
import { ref,reactive,computed,watch } from 'vue';import { useRoute } from 'vue-router';import { Plus,Search,Pencil,Trash2,ImagePlus,Settings2,Upload } from 'lucide-vue-next';import { api,url } from '../lib/api';import { currency,label } from '../lib/format';import { notify } from '../lib/ui';import StatePanel from '../components/StatePanel.vue';import StatusBadge from '../components/StatusBadge.vue';import AppModal from '../components/AppModal.vue';
const route=useRoute(),kind=computed(()=>route.path.split('/').at(-1)),roomsKind=computed(()=>kind.value==='rooms'),amenitiesKind=computed(()=>kind.value==='amenities');const rows=ref([]),types=ref([]),amenities=ref([]),loading=ref(true),error=ref(''),modal=ref(''),modalError=ref(''),busy=ref(false),item=ref(null),original=ref({}),form=reactive({}),meta=ref({total:0}),filter=reactive({search:'',status:'',page:1}),media=ref(null),file=ref(null),imageDescription=ref(''),imagePrimary=ref(true),selectedAmenities=ref([]);
const endpoint=computed(()=>'/admin/'+kind.value);const idKey=computed(()=>roomsKind.value?'room_id':amenitiesKind.value?'amenity_id':'room_type_id');
const fields=computed(()=>roomsKind.value?[['room_number','หมายเลขห้อง','text',true],['floor','ชั้น','number',true],['room_type_id','ประเภทห้อง','type',true],['room_status','สถานะห้อง','roomStatus',true],['note','หมายเหตุ','textarea',false]]:amenitiesKind.value?[['amenity_name','ชื่อสิ่งอำนวยความสะดวก','text',true],['icon','ชื่อไอคอน','text',false],['description','รายละเอียด','textarea',false],['status','สถานะ','status',true]]:[['type_name','ชื่อประเภทห้อง','text',true],['price_per_night','ราคาต่อคืน','money',true],['adult_capacity','ความจุผู้ใหญ่','number',true],['child_capacity','ความจุเด็ก','number',true],['bed_count','จำนวนเตียง','number',true],['bed_type','ประเภทเตียง','text',false],['room_size','ขนาดห้อง (ตร.ม.)','money',false],['description','รายละเอียด','textarea',false],['status','สถานะ','status',true]]);
async function load(){loading.value=true;error.value='';try{const q=new URLSearchParams({page:filter.page,limit:15});if(filter.search)q.set('search',filter.search);if(filter.status)q.set(roomsKind.value?'room_status':'status',filter.status);const result=await api(endpoint.value+(amenitiesKind.value?'':'?'+q));rows.value=amenitiesKind.value?result.data.filter(a=>!filter.search||a.amenity_name.includes(filter.search)):result.data;meta.value=result.meta||{total:rows.value.length};if(roomsKind.value)types.value=(await api('/admin/room-types?limit=100')).data;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(row){item.value=row||null;modalError.value='';Object.keys(form).forEach(k=>delete form[k]);const defaults=roomsKind.value?{room_number:'',floor:1,room_type_id:'',room_status:'available',note:''}:amenitiesKind.value?{amenity_name:'',icon:'',description:'',status:'active'}:{type_name:'',price_per_night:900,adult_capacity:2,child_capacity:0,bed_count:1,bed_type:'Double',room_size:'',description:'',status:'active'};fields.value.forEach(([k])=>form[k]=row?.[k]??defaults[k]);original.value={...form};modal.value='edit';}
async function save(){busy.value=true;modalError.value='';try{const body={};for(const [key,,type,required] of fields.value){let value=form[key];if(['number','money','type'].includes(type)){if(value===''||value===null){if(required)throw Error('กรุณากรอกข้อมูลที่จำเป็น');value=null;}else value=Number(value);}if(item.value&&String(value??'')===String(original.value[key]??''))continue;if(key==='room_status'&&value==='occupied')continue;body[key]=value;}if(!Object.keys(body).length){modal.value='';return;}await api(endpoint.value+(item.value?'/'+item.value[idKey.value]:''),{method:item.value?'PATCH':'POST',body});notify('บันทึกข้อมูลสำเร็จ');modal.value='';await load();}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
async function remove(){busy.value=true;modalError.value='';try{await api(endpoint.value+'/'+item.value[idKey.value],{method:'DELETE'});notify('ลบข้อมูลแล้ว');modal.value='';await load();}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
async function openMedia(row){item.value=row;modal.value='media';modalError.value='';media.value=null;file.value=null;try{const [t,a]=await Promise.all([api('/admin/room-types/'+row.room_type_id),api('/admin/amenities')]);media.value=t.data;amenities.value=a.data.filter(a=>a.status==='active');selectedAmenities.value=t.data.amenities.map(a=>a.amenity_id);}catch(e){modalError.value=e.message;}}
async function uploadImage(){busy.value=true;modalError.value='';try{if(!file.value)throw Error('กรุณาเลือกรูปภาพ');if(file.value.size>5*1024*1024)throw Error('ไฟล์ต้องไม่เกิน 5 MB');const body=new FormData();body.set('file',file.value);body.set('description',imageDescription.value);body.set('is_primary',String(imagePrimary.value));await api('/admin/room-types/'+item.value.room_type_id+'/images',{method:'POST',body});notify('เพิ่มรูปภาพแล้ว');await openMedia(item.value);}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
const imageDelete=ref(null);
async function deleteImage(){busy.value=true;modalError.value='';try{await api('/admin/room-images/'+imageDelete.value,{method:'DELETE'});imageDelete.value=null;await openMedia(item.value);notify('ลบรูปแล้ว');}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
async function saveAmenities(){busy.value=true;modalError.value='';try{await api('/admin/room-types/'+item.value.room_type_id+'/amenities',{method:'PUT',body:{amenity_ids:selectedAmenities.value}});notify('บันทึกสิ่งอำนวยความสะดวกแล้ว');}catch(e){modalError.value=e.message;}finally{busy.value=false;}}
function search(){filter.page=1;load();}watch(()=>route.path,()=>{modal.value='';filter.search='';filter.status='';filter.page=1;load();},{immediate:true});
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">HOTEL INVENTORY</p><h1>{{ route.meta.title }}</h1><p class="muted">{{ roomsKind?'จัดการห้องจริงและความพร้อมในการเข้าพัก':amenitiesKind?'จัดการบริการและสิ่งอำนวยความสะดวก':'กำหนดราคา ความจุ รูปภาพ และรายละเอียดห้อง' }}</p></div><button class="btn primary" @click="edit()"><Plus :size="18"/> {{ roomsKind?'เพิ่มห้องพัก':amenitiesKind?'เพิ่มรายการ':'เพิ่มประเภทห้อง' }}</button></div><form class="toolbar panel" @submit.prevent="search"><div class="search-input"><Search :size="17"/><input v-model="filter.search" :placeholder="roomsKind?'ค้นหาหมายเลขห้อง':'ค้นหาชื่อ'" aria-label="ค้นหา"/></div><select v-if="!amenitiesKind" v-model="filter.status" aria-label="กรองสถานะ"><option value="">ทุกสถานะ</option><template v-if="roomsKind"><option v-for="s in ['available','occupied','cleaning','maintenance','inactive']" :key="s" :value="s">{{ label(s) }}</option></template><template v-else><option value="active">ใช้งาน</option><option value="inactive">ปิดใช้งาน</option></template></select><button class="btn outline">ค้นหา</button></form><StatePanel :loading="loading" :error="error" :empty="!loading&&!error&&!rows.length" @retry="load"/><div v-if="rows.length&&!loading&&!error" class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>{{ roomsKind?'ห้องพัก':amenitiesKind?'รายการ':'ประเภทห้อง' }}</th><th v-if="roomsKind">ชั้น / ประเภท</th><th v-else-if="!amenitiesKind">ความจุ / เตียง</th><th v-if="!amenitiesKind">ราคา / คืน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr v-for="r in rows" :key="r[idKey]"><td><strong>{{ r.room_number||r.amenity_name||r.type_name }}</strong><small>{{ r.note||r.description||'—' }}</small></td><td v-if="roomsKind">ชั้น {{ r.floor }}<small>{{ r.type_name }}</small></td><td v-else-if="!amenitiesKind">{{ r.adult_capacity }} ผู้ใหญ่ · {{ r.child_capacity }} เด็ก<small>{{ r.bed_count }} เตียง · {{ r.bed_type }}</small></td><td v-if="!amenitiesKind">{{ currency(r.price_per_night) }}</td><td><StatusBadge :value="r.room_status||r.status"/></td><td><div class="button-row"><button class="icon-btn" :aria-label="'แก้ไข '+(r.room_number||r.type_name||r.amenity_name)" @click="edit(r)"><Pencil :size="17"/></button><button v-if="!roomsKind&&!amenitiesKind" class="icon-btn" aria-label="จัดการรูปและสิ่งอำนวยความสะดวก" @click="openMedia(r)"><ImagePlus :size="18"/></button><button v-if="!amenitiesKind" class="icon-btn text-danger" aria-label="ลบรายการ" @click="item=r;modal='delete';modalError='' "><Trash2 :size="17"/></button></div></td></tr></tbody></table></div></div><div v-if="meta.total&&!amenitiesKind" class="pagination"><span>{{ meta.total }} รายการ · หน้า {{ filter.page }}</span><div><button class="btn tiny outline" :disabled="filter.page===1||loading" @click="filter.page--;load()">ก่อนหน้า</button><button class="btn tiny outline" :disabled="filter.page*15>=meta.total||loading" @click="filter.page++;load()">ถัดไป</button></div></div><AppModal v-if="modal" :title="modal==='edit'?(item?'แก้ไขข้อมูล':'เพิ่มข้อมูล'):modal==='delete'?'ยืนยันการลบ':'รูปภาพและสิ่งอำนวยความสะดวก'" @close="!busy&&(modal='')"><div v-if="modalError" class="alert danger" role="alert">{{ modalError }}</div><form v-if="modal==='edit'" @submit.prevent="save"><div class="form-grid"><label v-for="[key,text,type,required] in fields" :key="key" :class="{'span-2':type==='textarea'}">{{ text }}<span v-if="required" class="required"> *</span><textarea v-if="type==='textarea'" v-model="form[key]" rows="3" maxlength="5000"></textarea><select v-else-if="type==='type'" v-model="form[key]" required><option disabled value="">เลือกประเภทห้อง</option><option v-for="t in types" :key="t.room_type_id" :value="t.room_type_id" :disabled="t.status!=='active'">{{ t.type_name }}{{ t.status!=='active'?' (ปิดใช้งาน)':'' }}</option></select><select v-else-if="type==='roomStatus'" v-model="form[key]" :disabled="form[key]==='occupied'"><option v-if="form[key]==='occupied'" value="occupied">มีผู้เข้าพัก</option><option v-for="s in ['available','cleaning','maintenance','inactive']" :key="s" :value="s">{{ label(s) }}</option></select><select v-else-if="type==='status'" v-model="form[key]"><option value="active">ใช้งาน</option><option value="inactive">ปิดใช้งาน</option></select><input v-else v-model="form[key]" :type="['number','money'].includes(type)?'number':'text'" :step="type==='money'?'0.01':'1'" :min="key==='floor'?undefined:['adult_capacity','bed_count'].includes(key)?1:0" :required="required" :maxlength="key==='room_number'?10:key==='bed_type'?50:100"/></label></div><div class="modal-actions"><button class="btn outline" type="button" @click="modal=''" :disabled="busy">ยกเลิก</button><button class="btn primary" :disabled="busy">{{ busy?'กำลังบันทึก…':'บันทึกข้อมูล' }}</button></div></form><template v-else-if="modal==='delete'"><p>ต้องการลบ <strong>{{ item.room_number||item.type_name }}</strong> ใช่ไหม?</p><p class="muted">รายการที่มีประวัติหรือข้อมูลอ้างอิงจะลบไม่ได้ ให้แก้สถานะเป็นปิดใช้งานแทน</p><div class="modal-actions"><button class="btn outline" @click="modal=''" :disabled="busy">กลับ</button><button class="btn danger" @click="remove" :disabled="busy">{{ busy?'กำลังลบ…':'ยืนยันลบ' }}</button></div></template><template v-else><StatePanel :loading="!media&&!modalError"/><template v-if="media"><h3>{{ media.type_name }}</h3><div class="media-grid"><div v-for="image in media.images" :key="image.image_id"><img :src="url(image.url)" alt="รูปห้องพัก"/><span v-if="image.is_primary" class="badge active">รูปหลัก</span><button class="icon-btn text-danger" @click="imageDelete=image.image_id" aria-label="ลบรูป"><Trash2 :size="16"/></button></div></div><div v-if="imageDelete" class="alert danger"><span>ยืนยันลบรูปนี้?</span><button class="btn tiny danger" @click="deleteImage" :disabled="busy">ลบรูป</button><button class="btn tiny outline" @click="imageDelete=null">กลับ</button></div><form @submit.prevent="uploadImage"><label>เพิ่มรูปภาพ<input type="file" accept="image/png,image/jpeg" @change="file=$event.target.files[0]" required/></label><label>คำอธิบาย<input v-model="imageDescription" maxlength="255"/></label><label class="checkbox"><input type="checkbox" v-model="imagePrimary"/>ใช้เป็นรูปหลัก</label><button class="btn outline full" :disabled="busy"><Upload :size="17"/> อัปโหลดรูป</button></form><hr/><h3>สิ่งอำนวยความสะดวก</h3><div class="amenity-checks"><label v-for="a in amenities" :key="a.amenity_id" class="checkbox"><input type="checkbox" :value="a.amenity_id" v-model="selectedAmenities"/>{{ a.amenity_name }}</label></div><button class="btn primary full" @click="saveAmenities" :disabled="busy">บันทึกสิ่งอำนวยความสะดวก</button></template></template></AppModal></section></template>
